    props: {
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: CarouselContentStyle,
    provide() {
        return {
            $pcCarouselContent: this,
            $parentInstance: this
        };
